def _atomic_write_checkpoint(path: str, checkpoint: dict) -> None:
    """Write the checkpoint in declared key order and atomically replace ``path``."""
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _atomic_write_bytes(path: str, payload: bytes) -> None:
    """Atomically replace ``path`` with ``payload``.

    The temp file is fsynced before the replace and the directory afterwards,
    mirroring the main store's durability rules.
    """
    directory = os.path.dirname(os.path.abspath(path)) or "."
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(prefix=".light-checkpoint-", dir=directory)
    promoted = False
    try:
        with os.fdopen(fd, "wb") as fh:
            fh.write(payload)
            fh.flush()
            os.fsync(fh.fileno())
        os.replace(tmp_path, path)
        promoted = True
        _fsync_dir(directory)
    finally:
        if not promoted and os.path.exists(tmp_path):
            try:
                os.unlink(tmp_path)
            except OSError:
                pass


def _read_bytes_or_none(path: str) -> bytes | None:
    """Raw bytes of ``path`` (None when absent); other read errors propagate."""
    try:
        with open(path, "rb") as fh:
            return fh.read()
    except FileNotFoundError:
        return None


def _restore_bytes(path: str, original: bytes | None) -> None:
    """Best-effort compensation: put ``original`` back at ``path``.

    A file that did not exist is unlinked again. Any failure is swallowed —
    the caller already reports ``io`` and the next strict load surfaces the
    corruption as ``state``.
    """
    try:
        if original is None:
            os.unlink(path)
        else:
            _atomic_write_bytes(path, original)
    except OSError:
        pass


def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so the checkpoint rename survives a crash."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)


# -- generation-history sidecar ------------------------------------------------


def _history_path(path: str) -> str:
    """The sidecar path mirroring one advance checkpoint path."""
    return path + ".history"


def _history_record(checkpoint: dict, prev: str) -> dict:
    """One sidecar record: ``{checkpoint, prev, hash}`` in declared key order.

    ``hash`` chains the record: SHA-256 over the ASCII bytes of ``prev``
    concatenated with the canonical (sorted, compact) JSON of the checkpoint.
    """
    ordered = {key: checkpoint[key] for key in CHECKPOINT_KEYS}
    digest = hashlib.sha256(
        prev.encode("ascii") + _canonical_json_bytes(ordered)
    ).hexdigest()
    return {"checkpoint": ordered, "prev": prev, "hash": digest}


def _atomic_write_history(path: str, document: dict) -> None:
    """Write the sidecar in declared key order and atomically replace ``path``."""
    ordered = {key: document[key] for key in HISTORY_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))


def _load_history(path: str) -> dict | None:
    """Strictly load and replay the generation-history sidecar.

    Returns None when no file exists at ``path``. Otherwise validates the
    exact key orders and JSON types, then replays every retained generation:
    record generations must run consecutively from ``base.generation + 1``,
    each ``prev`` must name the previous record's hash (the first names
    ``base.hash``), each record hash and the head are recomputed, and every
    checkpoint passes the same state-hash/context-replay checks as
    :func:`_load_checkpoint` plus anchor continuity with its predecessor. Any
    defect is a ``state`` failure (unreadable JSON is ``state`` too, an
    unreadable file ``io``); the file is never truncated or rebuilt.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc

    try:
        data = json.loads(text)
    except (ValueError, UnicodeDecodeError) as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_history_document(data)


def _validate_history_document(data: object) -> dict:
    """Validate and replay one parsed sidecar document."""
    if not isinstance(data, dict) or tuple(data.keys()) != HISTORY_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data["v"]) or data["v"] != HISTORY_VERSION:
        raise _CheckpointError(ERR_STATE)

    base = data["base"]
    if not isinstance(base, dict) or tuple(base.keys()) != HISTORY_BASE_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(base["generation"]) or base["generation"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(base["hash"]):
        raise _CheckpointError(ERR_STATE)

    records = data["records"]
    if not isinstance(records, list) or not records:
        raise _CheckpointError(ERR_STATE)
    head = data["head"]
    if not crypto.is_hex64(head):
        raise _CheckpointError(ERR_STATE)

    validated = []
    prev = base["hash"]
    previous_tip: dict | None = None
    for index, raw in enumerate(records):
        record = _validate_history_record(raw)
        checkpoint = record["checkpoint"]
        if checkpoint["generation"] != base["generation"] + 1 + index:
            raise _CheckpointError(ERR_STATE)
        if record["prev"] != prev:
            raise _CheckpointError(ERR_STATE)
        if record != _history_record(checkpoint, prev):
            raise _CheckpointError(ERR_STATE)
        _verify_checkpoint_document(checkpoint)
        if previous_tip is not None:
            # Consecutive checkpoints chain: each anchor is the previous tip.
            expected_anchor = {
                "height": previous_tip["height"],
                "block_hash": previous_tip["tip_hash"],
            }
            if checkpoint["anchor"] != expected_anchor:
                raise _CheckpointError(ERR_STATE)
        previous_tip = checkpoint["tip"]
        prev = record["hash"]
        validated.append(record)

    if head != validated[-1]["hash"]:
        raise _CheckpointError(ERR_STATE)
    return {
        "v": HISTORY_VERSION,
        "base": {
            "generation": base["generation"],
            "hash": base["hash"],
        },
        "records": validated,
        "head": head,
    }


def _validate_history_record(raw: object) -> dict:
    """Validate the exact key order and JSON types of one sidecar record."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HISTORY_RECORD_KEYS:
        raise _CheckpointError(ERR_STATE)
    checkpoint = _validate_checkpoint_shape(raw["checkpoint"])
    if not crypto.is_hex64(raw["prev"]):
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw["hash"]):
        raise _CheckpointError(ERR_STATE)
    return {"checkpoint": checkpoint, "prev": raw["prev"], "hash": raw["hash"]}


def history(path: str, generation: object = None, keep: object = None) -> dict:
    """Query or prune the generation-history sidecar of one advance checkpoint.

    ``generation`` and ``keep`` are mutually exclusive and, when given, must
    be non-boolean positive integers. Without either, the last generation's
    record is reported. With ``keep=n`` only the last ``min(n, count)``
    records are retained: when nothing is pruned the sidecar's bytes are left
    untouched, otherwise ``base`` advances to the last pruned record's
    ``{generation, hash}`` and the sidecar is rewritten under the same
    per-path lock as :func:`advance` (the checkpoint file never changes; an
    ``io`` failure restores the original bytes best-effort).

    Success returns ``{"ok", "base", "record", "head", "kept"}`` in that key
    order — ``record`` the queried (default last) or, with ``keep``, the last
    retained record, ``kept`` null for queries and the retained count for
    prunes. Failure returns ``{"ok": False, "error": category}`` with
    category one of ``input`` (bad arguments), ``io`` (the sidecar is missing
    or cannot be read/written) and ``state`` (the sidecar fails validation or
    the requested generation is not retained).
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if generation is not None and keep is not None:
        return {"ok": False, "error": ERR_INPUT}
    for parameter in (generation, keep):
        if parameter is not None and (not _is_int(parameter) or parameter < 1):
            return {"ok": False, "error": ERR_INPUT}

    lock = _checkpoint_lock(path)
    with lock:
        sidecar_path = _history_path(path)
        try:
            sidecar = _load_history(sidecar_path)
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}
        if sidecar is None:
            return {"ok": False, "error": ERR_IO}

        records = sidecar["records"]
        if keep is None:
            if generation is None:
                record = records[-1]
            else:
                record = next(
                    (
                        candidate
                        for candidate in records
                        if candidate["checkpoint"]["generation"] == generation
                    ),
                    None,
                )
                if record is None:
                    return {"ok": False, "error": ERR_STATE}
            return {
                "ok": True,
                "base": sidecar["base"],
                "record": record,
                "head": sidecar["head"],
                "kept": None,
            }

        kept = min(keep, len(records))
        record = records[-1]
        if kept == len(records):
            # Nothing pruned: the sidecar's bytes stay exactly as they were.
            return {
                "ok": True,
                "base": sidecar["base"],
                "record": record,
                "head": sidecar["head"],
                "kept": kept,
            }

        last_pruned = records[len(records) - kept - 1]
        base = {
            "generation": last_pruned["checkpoint"]["generation"],
            "hash": last_pruned["hash"],
        }
        rewritten = {
            "v": HISTORY_VERSION,
            "base": base,
            "records": records[len(records) - kept :],
            "head": sidecar["head"],
        }
        try:
            original = _read_bytes_or_none(sidecar_path)
        except OSError:
            return {"ok": False, "error": ERR_IO}
        try:
            _atomic_write_history(sidecar_path, rewritten)
        except OSError:
            # Compensate: put the original bytes back best-effort.
            _restore_bytes(sidecar_path, original)
            return {"ok": False, "error": ERR_IO}
        return {
            "ok": True,
            "base": base,
            "record": record,
            "head": sidecar["head"],
            "kept": kept,
        }


# -- signed history export / offline verification -----------------------------

# The exact top-level key order of one exported history page, and of its auth.
HISTORY_PAGE_KEYS = (
    "base",
    "records",
    "next",
    "head",
    "checkpoint",
    "auth",
)
HISTORY_PAGE_AUTH_KEYS = ("public_key", "signature")

# Page-size bounds for :func:`export_history`.
HISTORY_EXPORT_MIN_LIMIT = 1
HISTORY_EXPORT_MAX_LIMIT = 200
HISTORY_EXPORT_DEFAULT_LIMIT = 50


def export_history(
    path: object,
    key: object,
    after: object = None,
    limit: object = HISTORY_EXPORT_DEFAULT_LIMIT,
) -> dict:
    """Export one signed page of retained checkpoint history for offline use.

    Strictly reloads the checkpoint at ``path`` and its ``path + ".history"``
    sidecar and returns one page with the exact key order
    ``base, records, next, head, checkpoint, auth``:

    * ``base``/``records``/``head`` are the sidecar's own documents (nested
      key orders unchanged), ``checkpoint`` is the persisted five-key
      checkpoint document (identical to the last retained record's);
    * ``next`` is the last record generation of the page when another page
      follows, or ``null`` on the final page;
    * ``auth`` is ``{"public_key", "signature"}``: the Ed25519 public key
      derived from the 64-lowercase-hex seed ``key`` and its signature over the
      SHA-256 digest of the canonical (sorted, compact, non-ASCII-unescaped)
      JSON of the page with ``auth`` removed.

    ``after`` is ``None`` (page starts right after ``base``) or a non-boolean
    non-negative integer naming either ``base.generation`` or a retained
    generation that is not the last one; the page then starts at the following
    record. ``limit`` is a non-boolean integer in 1..200. Bad arguments are
    ``input``; a missing or unreadable file is ``io``; a corrupt checkpoint or
    sidecar, a sidecar/checkpoint mismatch or an unmatched/terminal cursor is
    ``state``.
    """
    if not isinstance(path, str) or not path:
        return {"ok": False, "error": ERR_INPUT}
    if not isinstance(key, str) or not _HEX32_RE.fullmatch(key):
        return {"ok": False, "error": ERR_INPUT}
    if after is not None and (not _is_int(after) or after < 0):
        return {"ok": False, "error": ERR_INPUT}
    if (
        not _is_int(limit)
        or limit < HISTORY_EXPORT_MIN_LIMIT
        or limit > HISTORY_EXPORT_MAX_LIMIT
    ):
        return {"ok": False, "error": ERR_INPUT}
    public_key = crypto.derive_public_key(key)
    if public_key is None:
        return {"ok": False, "error": ERR_INPUT}

    lock = _checkpoint_lock(path)
    with lock:
        try:
            checkpoint = _load_checkpoint(path)
            sidecar = _load_history(_history_path(path))
        except _CheckpointError as failure:
            return {"ok": False, "error": failure.category}
        if sidecar is None:
            # Nothing retained to export: the sidecar missing is an io defect.
            return {"ok": False, "error": ERR_IO}
        if checkpoint is None:
            # A sidecar without its checkpoint is unrecoverable corruption.
            return {"ok": False, "error": ERR_STATE}

        base = sidecar["base"]
        records = sidecar["records"]
        if records[-1]["checkpoint"] != checkpoint:
            # The sidecar tip must pin the persisted checkpoint.
            return {"ok": False, "error": ERR_STATE}

        if after is None or after == base["generation"]:
            start = 0
        else:
            start = next(
                (
                    index + 1
                    for index, record in enumerate(records)
                    if record["checkpoint"]["generation"] == after
                ),
                None,
            )
            # An unknown cursor, or one naming the last retained generation
            # (nothing follows it), is a state defect rather than an input one:
            # the argument has a legal shape but does not name a usable cursor.
            if start is None or start >= len(records):
                return {"ok": False, "error": ERR_STATE}

        page_records = records[start : start + limit]
        has_next = start + limit < len(records)
        next_value = (
            page_records[-1]["checkpoint"]["generation"] if has_next else None
        )
        page = {
            "base": base,
            "records": page_records,
            "next": next_value,
            "head": sidecar["head"],
            "checkpoint": checkpoint,
        }
        digest = hashlib.sha256(_canonical_json_bytes(page)).digest()
        signature = crypto.sign_message(key, digest)
        if signature is None:
            return {"ok": False, "error": ERR_INPUT}
        page["auth"] = {"public_key": public_key, "signature": signature}
        return {name: page[name] for name in HISTORY_PAGE_KEYS}


def verify_history(pages: object, public_key: object) -> dict:
    """Verify an ordered, non-empty batch of signed history pages offline.

    Every page must have the exact key order
    ``base, records, next, head, checkpoint, auth`` (nested documents keep
    their declared orders and types) and carry
    ``auth = {"public_key", "signature"}``. The pinned ``public_key`` (64
    lowercase hex) must match every page's signing key and verify every
    Ed25519 signature over the auth-less canonical page digest; ``base``,
    ``head`` and the page ``checkpoint`` must be identical across all pages.

    Records must run consecutively from ``base.generation + 1`` with each
    ``prev``/``hash`` link recomputed, chaining across page seams in step with
    each non-final page's ``next`` cursor; every checkpoint is replayed (state
    hash plus its stored batch context) with anchor continuity between
    consecutive checkpoints. Only the final page may carry ``next: null``; its
    last record's hash must equal ``head`` and its checkpoint must equal the
    page checkpoint. Missing, duplicate or reordered pages and any tampering
    are rejected.

    Returns ``{"ok": True}`` on success or ``{"ok": False, "error":
    category}`` on failure with category one of ``input`` (structure/types),
    ``auth`` (pinned key or a failing signature) and ``integrity`` (chaining,
    pagination or checkpoint replay). Never raises for malformed input.
    """
    try:
        _verify_history_pages(pages, public_key)
    except _Failure as failure:
        return {"ok": False, "error": failure.category}
    except Exception:
        # Defensive: structurally unforeseeable inputs must report rather than
        # crash the verifying process.
        return {"ok": False, "error": ERR_INPUT}
    return {"ok": True}


def _validate_page_base(raw: object) -> dict:
    """Validate one exported page's ``{generation, hash}`` base document."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HISTORY_BASE_KEYS:
        raise _Failure(ERR_INPUT)
    if not _is_int(raw["generation"]) or raw["generation"] < 0:
        raise _Failure(ERR_INPUT)
    if not crypto.is_hex64(raw["hash"]):
        raise _Failure(ERR_INPUT)
    return {"generation": raw["generation"], "hash": raw["hash"]}


def _validate_page_checkpoint(raw: object) -> dict:
    """Shape-validate a checkpoint embedded in an exported history page.

    Shape/type defects are the page's structural defects (``input``); the
    state hash and context replay are judged separately as ``integrity``.
    """
    try:
        return _validate_checkpoint_shape(raw)
    except _CheckpointError:
        raise _Failure(ERR_INPUT) from None


def _validate_page_record(raw: object) -> dict:
    """Validate one ``{checkpoint, prev, hash}`` record embedded in a page."""
    if not isinstance(raw, dict) or tuple(raw.keys()) != HISTORY_RECORD_KEYS:
        raise _Failure(ERR_INPUT)
    checkpoint = _validate_page_checkpoint(raw["checkpoint"])
    if not crypto.is_hex64(raw["prev"]) or not crypto.is_hex64(raw["hash"]):
        raise _Failure(ERR_INPUT)
    return {"checkpoint": checkpoint, "prev": raw["prev"], "hash": raw["hash"]}


def _verify_history_pages(pages: object, pinned_key: object) -> None:
    """All structural, authentication and chaining checks for :func:`verify_history`."""
    if not isinstance(pages, list) or not pages:
        raise _Failure(ERR_INPUT)
    if not isinstance(pinned_key, str) or not _HEX32_RE.fullmatch(pinned_key):
        raise _Failure(ERR_INPUT)

    common_base: dict | None = None
    common_head: str | None = None
    common_checkpoint: dict | None = None
    # Linkage state carried across page seams.
    expected_prev: str | None = None
    expected_generation: int | None = None
    previous_tip: dict | None = None

    for position, raw_page in enumerate(pages):
        is_last_page = position == len(pages) - 1
        if not isinstance(raw_page, dict) or tuple(raw_page.keys()) != HISTORY_PAGE_KEYS:
            raise _Failure(ERR_INPUT)
        auth = raw_page["auth"]
        if not isinstance(auth, dict) or tuple(auth.keys()) != HISTORY_PAGE_AUTH_KEYS:
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex64(auth["public_key"]):
            raise _Failure(ERR_INPUT)
        if not crypto.is_hex128(auth["signature"]):
            raise _Failure(ERR_INPUT)
        base = _validate_page_base(raw_page["base"])
        head = raw_page["head"]
        if not crypto.is_hex64(head):
            raise _Failure(ERR_INPUT)
        page_checkpoint = _validate_page_checkpoint(raw_page["checkpoint"])
        records = raw_page["records"]
        if not isinstance(records, list) or not records:
            raise _Failure(ERR_INPUT)
        next_value = raw_page["next"]
        if next_value is not None and (not _is_int(next_value) or next_value < 0):
            raise _Failure(ERR_INPUT)
        # Every embedded record is shape- and type-validated up front, so a
        # structurally malformed page reports ``input`` even if its (now
        # mismatched) signature would fail too — structure precedes trust.
        validated_records = [_validate_page_record(raw) for raw in records]

        # The pinned trust anchor and the signed envelope must be shared by
        # every page of the export.
        if auth["public_key"] != pinned_key:
            raise _Failure(ERR_AUTH)
        if common_base is None:
            common_base = base
            common_head = head
            common_checkpoint = page_checkpoint
        elif base != common_base:
            raise _Failure(ERR_INTEGRITY)
        elif head != common_head or page_checkpoint != common_checkpoint:
            raise _Failure(ERR_INTEGRITY)

        # The signature covers the page verbatim minus auth, canonicalized the
        # same way the exporter canonicalizes it.
        unsigned = {
            key: raw_page[key] for key in HISTORY_PAGE_KEYS if key != "auth"
        }
        digest = hashlib.sha256(_canonical_json_bytes(unsigned)).digest()
        if not crypto.verify_signature(pinned_key, digest, auth["signature"]):
            raise _Failure(ERR_AUTH)

        if expected_prev is None:
            # The first page starts right at the shared base.
            expected_prev = base["hash"]
            expected_generation = base["generation"] + 1

        for record in validated_records:
            checkpoint = record["checkpoint"]
            if checkpoint["generation"] != expected_generation:
                # A gap, duplicate or reordered page breaks generation order.
                raise _Failure(ERR_INTEGRITY)
            if record["prev"] != expected_prev:
                raise _Failure(ERR_INTEGRITY)
            rebuilt = _history_record(checkpoint, expected_prev)
            if record["hash"] != rebuilt["hash"]:
                raise _Failure(ERR_INTEGRITY)
            # The state hash pins the document; the stored batch must replay
            # from its anchor to its tip and reproduce the verified tx ids.
            try:
                _verify_checkpoint_document(checkpoint)
            except _CheckpointError:
                raise _Failure(ERR_INTEGRITY) from None
            if previous_tip is not None:
                expected_anchor = {
                    "height": previous_tip["height"],
                    "block_hash": previous_tip["tip_hash"],
                }
                if checkpoint["anchor"] != expected_anchor:
                    raise _Failure(ERR_INTEGRITY)
            previous_tip = checkpoint["tip"]
            expected_prev = record["hash"]
            expected_generation += 1

        last_generation = records[-1]["checkpoint"]["generation"]
        if is_last_page:
            if next_value is not None:
                raise _Failure(ERR_INTEGRITY)
        else:
            # A non-final page must name its last record as the cursor the next
            # page continues from.
            if next_value != last_generation:
                raise _Failure(ERR_INTEGRITY)

    # The final page closes the export: its last record is the sidecar head and
    # its checkpoint is the page checkpoint shared by every page.
    final_record = _validate_page_record(pages[-1]["records"][-1])
    if final_record["hash"] != common_head:
        raise _Failure(ERR_INTEGRITY)
    if final_record["checkpoint"] != common_checkpoint:
        raise _Failure(ERR_INTEGRITY)

"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

        {"height": H, "block_hash": B, "merkle_root": R,
         "transaction_ids": [id, ...],     # ALL block leaves, ascending
         "proofs": [{"tx_id", "index", "siblings"}, ...]}  # requested subset

    ``transaction_ids`` is the block's complete, ascending leaf list; ``proofs``
    covers the requested tx_ids (a subset of it), itself sorted by tx_id. Every
    proof's leaf-to-root sibling path is re-hashed with the same pairing rules
    as :func:`merkle_root` (``sha256(left + right)`` hex pairs, a lone odd node
    paired with itself); the root is additionally recomputed directly from
    ``transaction_ids`` and must equal both the bundle's ``merkle_root`` and
    ``expected_merkle_root``, while ``block_hash`` must equal
    ``expected_block_hash``. Each proof ``index`` must be the tx_id's exact
    position in ``transaction_ids`` and its path must agree with that index at
    every level.

    Every defect — a missing/extra key, a wrong key order, a wrong type, a
    non-boolean/negative height, a duplicate/non-hex/non-string/unsorted tx_id,
    an unknown or duplicated proof tx_id, an out-of-range index, a path
    inconsistent with the index (including the phantom self-pair slot), an
    illegal direction or hash, excessive depth, an empty proof list, a tampered
    leaf list/root or block hash — returns False rather than raising.
    """
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS):
            return False
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root):
            return False
        height = bundle["height"]
        block_hash = bundle["block_hash"]
        bundle_root = bundle["merkle_root"]
        transaction_ids = bundle["transaction_ids"]
        proofs = bundle["proofs"]

        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return False
        if not _is_hex64(block_hash):
            return False
        if not _is_hex64(bundle_root):
            return False
        if not isinstance(transaction_ids, list) or not transaction_ids:
            return False
        if not isinstance(proofs, list) or not proofs:
            return False
        if any(not _is_hex64(tx_id) for tx_id in transaction_ids):
            return False
        # Unique leaves ...
        if len(set(transaction_ids)) != len(transaction_ids):
            return False
        # ... in ascending tx_id order, matching the block's leaf ordering.
        if transaction_ids != sorted(transaction_ids):
            return False
        # The root is recomputed straight from the claimed leaf list, so the
        # list can never be tampered with independently of the paths.
        if not hmac.compare_digest(merkle_root(transaction_ids), bundle_root):
            return False

        positions = {tx_id: i for i, tx_id in enumerate(transaction_ids)}
        proof_ids: list[str] = []
        leaf_count = len(transaction_ids)
        for proof in proofs:
            if not _exact_keys(proof, _BUNDLE_PROOF_KEYS):
                return False
            tx_id = proof["tx_id"]
            index = proof["index"]
            siblings = proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions:
                return False
            if tx_id in proof_ids:
                return False
            if isinstance(index, bool) or not isinstance(index, int):
                return False
            # The index must be exactly the tx_id's leaf position; anything
            # else is a mismatch or out of range regardless of supplied hashes.
            if index != positions[tx_id] or not 0 <= index < leaf_count:
                return False
            if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
                return False

            # A depth-D path addresses one of 2**D leaf slots.
            depth = len(siblings)
            if index >= (1 << depth):
                return False
            current = tx_id
            position = index
            for item in siblings:
                if not _exact_keys(item, _BUNDLE_SIBLING_KEYS):
                    return False
                direction = item["direction"]
                sibling_hash = item["hash"]
                if not _is_hex64(sibling_hash):
                    return False
                # The odd-node promotion pairs the last (even-positioned) node
                # with a copy of itself, so a genuine self-pair always points
                # at a right sibling. A left sibling equal to the current node
                # addresses the phantom duplicate slot, which is never a real
                # leaf. The path must also agree with the index at every
                # level: an even position is the left child (sibling on its
                # right), an odd position the right child.
                if direction == "left":
                    if position % 2 == 0 or sibling_hash == current:
                        return False
                    pair = sibling_hash + current
                elif direction == "right":
                    if position % 2 == 1:
                        return False
                    pair = current + sibling_hash
                else:
                    return False
                current = sha256_hex(pair.encode("ascii"))
                position //= 2

            if not hmac.compare_digest(current, bundle_root):
                return False
            proof_ids.append(tx_id)

        # Proofs must be unique and ordered by tx_id ascending.
        if proof_ids != sorted(proof_ids):
            return False

        if not hmac.compare_digest(bundle_root, expected_merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# -- account state Merkle tree ----------------------------------------------


def account_state_leaf(
    account: str, balance: int, confirmed_transactions: list[str]
) -> str:
    """SHA-256 leaf of one account's confirmed state.

    The leaf is ``sha256(utf8(JSON))`` of the canonical compact JSON document
    ``{"account":a,"balance":b,"confirmed_transactions":T}`` serialized with
    ``sort_keys=True``, ``ensure_ascii=False`` and ``separators=(",",":")``.
    ``T`` keeps its original (on-chain) order; ``sort_keys`` only orders the
    three top-level keys.
    """
    document = {
        "account": account,
        "balance": balance,
        "confirmed_transactions": confirmed_transactions,
    }
    raw = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return sha256_hex(raw)


def account_state_root(leaves: list[str]) -> str:
    """Merkle root of account-state leaves ordered by ascending account.

    Uses the same pairing rules as :func:`merkle_root` (hex-string pairs
    hashed ``sha256(left + right)``, a lone odd node paired with itself); an
    empty account set has the same root as an empty tx list.
    """
    return merkle_root(leaves)


def verify_account_proof(
    proof: object,
    expected_root: object,
    expected_height: object,
    expected_hash: object,
) -> bool:
    """Verify an account-state Merkle proof offline.

    Recomputes the account leaf from
    ``{account, balance, confirmed_transactions}``, walks the leaf-to-root
    ``siblings`` path, and requires the recomputed root to equal both the
    proof's ``state_root`` and ``expected_root``, while ``height`` /
    ``block_hash`` anchor the tree to the expected confirmed tip. Every
    malformed input — a non-64-char lowercase hex hash or anchor, an illegal
    direction, an illegal index, a malformed leaf/balance/transaction list, a
    path inconsistent with the index, excessive depth — returns False rather
    than raising.
    """
    try:
        if not isinstance(proof, dict):
            return False
        account = proof.get("account")
        balance = proof.get("balance")
        transactions = proof.get("confirmed_transactions")
        index = proof.get("index")
        state_root = proof.get("state_root")
        height = proof.get("height")
        block_hash = proof.get("block_hash")
        siblings = proof.get("siblings")

        if not isinstance(account, str) or not account:
            return False
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            return False
        if not isinstance(transactions, list):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transactions):
            return False
        if isinstance(index, bool) or not isinstance(index, int) or index < 0:
            return False
        if not isinstance(height, bool) and isinstance(height, int):
            if height < 0:
                return False
        else:
            return False
        if not _is_hex64(state_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_hash):
            return False
        if not _is_hex64(expected_root):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        # The leaf is always recomputed from the proof's own triple; a
        # client-supplied leaf value is never trusted.
        depth = len(siblings)
        # A depth-D path addresses one of 2**D leaf slots; a single-leaf tree
        # (D == 0) can only ever be index 0. An index outside that range is
        # illegal regardless of any hashes the caller supplies.
        if index >= (1 << depth):
            return False
        current = account_state_leaf(account, balance, transactions)
        position = index
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            # The odd-node promotion pairs the last (even-positioned) node
            # with a copy of itself, so a genuine self-pair always points at a
            # right sibling. A left sibling equal to the current node addresses
            # the phantom duplicate slot, which is never a real account.
            if direction == "left" and sibling_hash == current:
                return False
            # The path must agree with the index: at every level an even
            # position is the left child (sibling on its right) and an odd
            # position the right child.
            if direction == "left":
                if position % 2 == 0:
                    return False
                pair = sibling_hash + current
            elif direction == "right":
                if position % 2 == 1:
                    return False
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))
            position //= 2

        if not hmac.compare_digest(current, state_root):
            return False
        if not hmac.compare_digest(current, expected_root):
            return False
        if height != expected_height:
            return False
        if not hmac.compare_digest(block_hash, expected_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False

